SELECT YEAR(products.launch_date) launch_year, DATE_FORMAT(products.launch_date, 'yyyy-MM') launch_month, ROUND(AVG(order_items.quantity), 2) avg_quantity, MAX(order_items.quantity) max_quantity FROM order_items INNER JOIN products ON order_items.product_id = products.id GROUP BY YEAR(products.launch_date), DATE_FORMAT(products.launch_date, 'yyyy-MM') HAVING ROUND(AVG(order_items.quantity), 2) >= 45 ORDER BY max_quantity, launch_month DESC
